            }

            if (!tryParse)
            {
                throw new ArgumentException("Invalid network.", nameof(network));
            }

            ipnetwork = null;
            return false;
        }

        if (args.Length == 2)
        {
            if (byte.TryParse(args[1], out byte cidr1))
            {
